1	package com.example.starter.translation.api;
2	
3	import com.example.starter.translation.service.TranslationService;
4	import com.example.starter.translation.service.WriteExecutor;
5	import com.example.starter.translation.service.WriteResult;
6	import com.fasterxml.jackson.databind.ObjectMapper;
7	import jakarta.validation.Valid;
8	import org.springframework.http.MediaType;
9	import org.springframework.http.ResponseEntity;
10	import org.springframework.web.bind.annotation.GetMapping;
11	import org.springframework.web.bind.annotation.PathVariable;
12	import org.springframework.web.bind.annotation.PostMapping;
13	import org.springframework.web.bind.annotation.PutMapping;
14	import org.springframework.web.bind.annotation.RequestBody;
15	import org.springframework.web.bind.annotation.RequestHeader;
16	import org.springframework.web.bind.annotation.RequestMapping;
17	import org.springframework.web.bind.annotation.RestController;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.HexFormat;
23	
24	/**
25	 * 多语种段落修订与发布快照 REST API。
26	 * 所有写操作携带全局唯一 requestId 做幂等去重；提交/批准以 X-Actor-Id 表示本地操作者。
27	 */
28	@RestController
29	@RequestMapping("/api/documents")
30	public class TranslationController {
31	
32	    private final TranslationService translationService;
33	    private final WriteExecutor writeExecutor;
34	    private final ObjectMapper objectMapper;
35	
36	    public TranslationController(TranslationService translationService, WriteExecutor writeExecutor,
37	                                 ObjectMapper objectMapper) {
38	        this.translationService = translationService;
39	        this.writeExecutor = writeExecutor;
40	        this.objectMapper = objectMapper;
41	    }
42	
43	    /** 建文档：1~5 种目标语言，可携带初始段落。 */
44	    @PostMapping
45	    public ResponseEntity<String> createDocument(@Valid @RequestBody ApiDtos.CreateDocumentRequest request) {
46	        return writeExecutor.execute(request.requestId(), hash("POST /api/documents", request),
47	                () -> WriteResult.of(201, translationService.createDocument(request))).toResponseEntity();
48	    }
49	
50	    /** 增加段落：文档草稿版本加一。 */
51	    @PostMapping("/{documentId}/segments")
52	    public ResponseEntity<String> addSegment(@PathVariable long documentId,
53	                                             @Valid @RequestBody ApiDtos.AddSegmentRequest request) {
54	        String operation = "POST /api/documents/" + documentId + "/segments";
55	        return writeExecutor.execute(request.requestId(), hash(operation, request),
56	                () -> WriteResult.of(201, translationService.addSegment(documentId, request))).toResponseEntity();
57	    }
58	
59	    /** 源文修订：源文版本加一、相关译文待更新、草稿版本加一；不影响已发布快照。 */
60	    @PutMapping("/{documentId}/segments/{segmentId}/source")
61	    public ResponseEntity<String> reviseSource(@PathVariable long documentId, @PathVariable String segmentId,
62	                                               @Valid @RequestBody ApiDtos.ReviseSourceRequest request) {
63	        String operation = "PUT /api/documents/" + documentId + "/segments/" + segmentId + "/source";
64	        return writeExecutor.execute(request.requestId(), hash(operation, request),
65	                () -> WriteResult.of(200, translationService.reviseSource(documentId, segmentId, request)))
66	                .toResponseEntity();
67	    }
68	
69	    /** 译文提交：作者取 X-Actor-Id，所依据源文版本必须匹配当前源文版本。 */
70	    @PutMapping("/{documentId}/segments/{segmentId}/translations/{language}")
71	    public ResponseEntity<String> submitTranslation(@PathVariable long documentId, @PathVariable String segmentId,
72	                                                    @PathVariable String language,
73	                                                    @RequestHeader("X-Actor-Id") String actorId,
74	                                                    @Valid @RequestBody ApiDtos.SubmitTranslationRequest request) {
75	        String operation = "PUT /api/documents/" + documentId + "/segments/" + segmentId
76	                + "/translations/" + language;
77	        return writeExecutor.execute(request.requestId(), hash(operation, actorId, request),
78	                () -> WriteResult.of(200, translationService.submitTranslation(
79	                        documentId, segmentId, language, actorId, request))).toResponseEntity();
80	    }
81	
82	    /** 译文批准：审核人取 X-Actor-Id，不得是作者，须同时匹配当前源文与译文版本。 */
83	    @PostMapping("/{documentId}/segments/{segmentId}/translations/{language}/approve")
84	    public ResponseEntity<String> approveTranslation(@PathVariable long documentId, @PathVariable String segmentId,
85	                                                     @PathVariable String language,
86	                                                     @RequestHeader("X-Actor-Id") String actorId,
87	                                                     @Valid @RequestBody ApiDtos.ApproveTranslationRequest request) {
88	        String operation = "POST /api/documents/" + documentId + "/segments/" + segmentId
89	                + "/translations/" + language + "/approve";
90	        return writeExecutor.execute(request.requestId(), hash(operation, actorId, request),
91	                () -> WriteResult.of(200, translationService.approveTranslation(
92	                        documentId, segmentId, language, actorId, request))).toResponseEntity();
93	    }
94	
95	    /** 发布：全部段落全部目标语言均有有效批准时原子生成只读快照并递增发布版本。 */
96	    @PostMapping("/{documentId}/publish")
97	    public ResponseEntity<String> publish(@PathVariable long documentId,
98	                                          @Valid @RequestBody ApiDtos.PublishRequest request) {
99	        String operation = "POST /api/documents/" + documentId + "/publish";
100	        return writeExecutor.execute(request.requestId(), hash(operation, request),
101	                () -> WriteResult.of(201, translationService.publish(documentId, request))).toResponseEntity();
102	    }
103	
104	    /** 查询指定发布版本的只读快照。 */
105	    @GetMapping("/{documentId}/releases/{publishedVersion}")
106	    public ResponseEntity<String> getRelease(@PathVariable long documentId, @PathVariable int publishedVersion) {
107	        return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON)
108	                .body(translationService.getRelease(documentId, publishedVersion));
109	    }
110	
111	    /** 计算请求摘要：操作（含路径变量）+ 操作者 + 规范化请求体的 SHA-256。 */
112	    private String hash(String operation, Object... parts) {
113	        try {
114	            StringBuilder canonical = new StringBuilder(operation);
115	            for (Object part : parts) {
116	                canonical.append('\n').append(objectMapper.writeValueAsString(part));
117	            }
118	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
119	            return HexFormat.of().formatHex(digest.digest(canonical.toString().getBytes(StandardCharsets.UTF_8)));
120	        } catch (NoSuchAlgorithmException e) {
121	            throw new IllegalStateException("SHA-256 不可用", e);
122	        } catch (Exception e) {
123	            throw new IllegalArgumentException("请求序列化失败", e);
124	        }
125	    }
126	}
