1	package com.example.starter.translation;
2	
3	import com.fasterxml.jackson.databind.JsonNode;
4	import com.fasterxml.jackson.databind.ObjectMapper;
5	import org.junit.jupiter.api.BeforeEach;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
8	import org.springframework.boot.test.context.SpringBootTest;
9	import org.springframework.jdbc.core.JdbcTemplate;
10	import org.springframework.test.context.ActiveProfiles;
11	import org.springframework.test.web.servlet.MockMvc;
12	import org.springframework.test.web.servlet.MvcResult;
13	import org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;
14	import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;
15	
16	import java.util.UUID;
17	
18	/**
19	 * 集成测试基类：独立 H2 内存库（translation_test），每个用例前清空全部业务表，
20	 * 避免用例间顺序依赖；测试上下文关闭时连接池关闭，内存库随之释放。
21	 */
22	@SpringBootTest
23	@AutoConfigureMockMvc
24	@ActiveProfiles("test")
25	public abstract class AbstractIntegrationTest {
26	
27	    @Autowired
28	    protected MockMvc mockMvc;
29	
30	    @Autowired
31	    protected JdbcTemplate jdbc;
32	
33	    @Autowired
34	    protected ObjectMapper objectMapper;
35	
36	    @BeforeEach
37	    void cleanTables() {
38	        jdbc.update("DELETE FROM approval");
39	        jdbc.update("DELETE FROM translation");
40	        jdbc.update("DELETE FROM segment");
41	        jdbc.update("DELETE FROM release_snapshot");
42	        jdbc.update("DELETE FROM request_log");
43	        jdbc.update("DELETE FROM document");
44	    }
45	
46	    protected String newRequestId() {
47	        return UUID.randomUUID().toString();
48	    }
49	
50	    /** POST JSON，返回响应状态与解析后的响应体。 */
51	    protected ApiResult postJson(String url, String body) throws Exception {
52	        return perform(MockMvcRequestBuilders.post(url), body, null);
53	    }
54	
55	    protected ApiResult postJson(String url, String body, String actorId) throws Exception {
56	        return perform(MockMvcRequestBuilders.post(url), body, actorId);
57	    }
58	
59	    protected ApiResult putJson(String url, String body) throws Exception {
60	        return perform(MockMvcRequestBuilders.put(url), body, null);
61	    }
62	
63	    protected ApiResult putJson(String url, String body, String actorId) throws Exception {
64	        return perform(MockMvcRequestBuilders.put(url), body, actorId);
65	    }
66	
67	    protected ApiResult getJson(String url) throws Exception {
68	        MvcResult result = mockMvc.perform(MockMvcRequestBuilders.get(url)).andReturn();
69	        return toApiResult(result);
70	    }
71	
72	    private ApiResult perform(MockHttpServletRequestBuilder builder, String body, String actorId)
73	            throws Exception {
74	        builder.contentType("application/json").content(body);
75	        if (actorId != null) {
76	            builder.header("X-Actor-Id", actorId);
77	        }
78	        MvcResult result = mockMvc.perform(builder).andReturn();
79	        return toApiResult(result);
80	    }
81	
82	    private ApiResult toApiResult(MvcResult result) throws Exception {
83	        int status = result.getResponse().getStatus();
84	        String content = result.getResponse().getContentAsString();
85	        JsonNode json = content.isBlank() ? null : objectMapper.readTree(content);
86	        return new ApiResult(status, json);
87	    }
88	
89	    /** 建文档并返回 documentId。 */
90	    protected long createDocument(String requestId, String targetLanguagesJson, String segmentsJson)
91	            throws Exception {
92	        String body = "{\"requestId\":\"" + requestId + "\",\"targetLanguages\":" + targetLanguagesJson
93	                + ",\"segments\":" + segmentsJson + "}";
94	        ApiResult result = postJson("/api/documents", body);
95	        if (result.status() != 201) {
96	            throw new IllegalStateException("建文档失败: " + result.status() + " " + result.body());
97	        }
98	        return result.body().get("documentId").asLong();
99	    }
100	
101	    protected ApiResult submitTranslation(long documentId, String segmentId, String language, String actorId,
102	                                          String content, int sourceVersion, String requestId) throws Exception {
103	        String body = "{\"requestId\":\"" + requestId + "\",\"content\":\"" + content
104	                + "\",\"sourceVersion\":" + sourceVersion + "}";
105	        return putJson("/api/documents/" + documentId + "/segments/" + segmentId + "/translations/" + language,
