        return "[{\"segmentId\":\"s1\",\"language\":\"en\",\"expectedTranslationVersion\":" + v1 + "},"
                + "{\"segmentId\":\"s2\",\"language\":\"en\",\"expectedTranslationVersion\":" + v2 + "}]";
    }

